import { readFile } from "node:fs/promises";
import fixture from "./fixtures/main-legacy-save.json";
import {
  INVALID_BACKUP_KEY,
  QUEST_SAVE_KEY,
  STARTER_DAILY,
  VALID_BACKUP_KEY,
  advanceToDay,
  chooseOption,
  completeQuest,
  dailyPanel,
  expect,
  expectStreak,
  historyCard,
  historyDateSection,
  openApp,
  personalPanel,
  questRow,
  readStorage,
  reloadApp,
  seedStorage,
  test,
} from "./support";
import type { Page } from "@playwright/test";

/**
 * Regression tests for saves made by older versions. The fixture is a real save generated by playing
 * the app on main before Stage 1B. See its _about note. It must not be edited, so anything normal
 * play cannot produce is added on top of it inside the test that needs it.
 */

const ORIGINAL = JSON.stringify(fixture.save);
const WEDNESDAY = "2026-10-21T11:00:00Z";
const WEDNESDAY_LABEL = "Wednesday, October 21";

const QUICK_HABIT = "Quick habit on main";
const MON_WED = "Form Mon Wed on main";
const DATED = "Form dated on main";
const QUICK_ERRAND = "Quick errand on main";

type Quest = Record<string, unknown>;

async function loadFixture(page: Page, save: unknown = fixture.save) {
  await page.clock.setSystemTime(WEDNESDAY);
  await seedStorage(page, { [QUEST_SAVE_KEY]: JSON.stringify(save) });
  await openApp(page);
  await expect(page.getByText(WEDNESDAY_LABEL, { exact: true })).toBeVisible();
}

async function saved(page: Page) {
  return JSON.parse((await readStorage(page, QUEST_SAVE_KEY))!);
}

function progressText(page: Page) {
  return page.getByRole("region", { name: "Your progress" });
}

async function describeRows(page: Page, panelName: string) {
  const rows = await page.getByRole("region", { name: panelName }).getByRole("listitem").all();
  return Promise.all(rows.map(async (row) => ({
    title: await row.locator("strong").first().innerText(),
    done: await row.getByRole("button", { name: /^Mark incomplete/ }).count() > 0,
  })));
}

test.describe("A real save from main", () => {
  test("the fixture really is in the old format", () => {
    const quests: Quest[] = [...fixture.save.questLists.daily, ...fixture.save.questLists.personal];

    expect(quests.length).toBe(10);
    expect(quests.every((quest) => "schedule" in quest)).toBe(true);
    expect(fixture.save.questLists.daily.filter((quest) => !("repeatSchedule" in quest))).toHaveLength(5);
    expect(fixture.save.schemaVersion).toBe(5);
  });

  test("shows everything main showed for the same save", async ({ page }) => {
    const expected = fixture.observedOnMain;
    await loadFixture(page);

    expect((await progressText(page).innerText()).replace(/\s+/g, " ")).toBe(expected.progress);
    expect(await describeRows(page, "Daily Quests")).toEqual(expected.daily);
    expect(await describeRows(page, "Personal Quests")).toEqual(expected.personal);
    await expect(page.getByText(expected.collection)).toBeVisible();
    await expect(page.getByRole("link", { name: expected.gift })).toBeVisible();

    await openApp(page, "/all-quests");
    expect((await describeRows(page, "Daily Quests")).map((row) => row.title)).toEqual(expected.allDailyTitles);

    await openApp(page, "/completion-history");
    const summaries = await page.locator("summary").allInnerTexts();
    expect(summaries.map((summary) => summary.replace(/\s+/g, " "))).toEqual(expected.summaries);
    await expect(page.getByRole("article")).toHaveCount(expected.openCards);
    await expect(page.getByText("Earlier completions")).toHaveCount(expected.earlier);
  });

  test("converts recurrence, removes legacy text, and leaves progress data byte-identical", async ({ page }) => {
    await loadFixture(page);
    await expect.poll(async () => JSON.stringify((await saved(page)).questLists)).not.toContain('"schedule"');

    const save = await saved(page);
    expect(save.schemaVersion).toBe(5);
    expect(save.questLists.daily.map((quest: Quest) => [quest.title, quest.repeatSchedule, quest.selectedDays])).toEqual([
      ...STARTER_DAILY.map((title) => [title, "Every day", ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]]),
      [QUICK_HABIT, "Every day", ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]],
      [MON_WED, "Selected days", ["Mon", "Wed"]],
    ]);
    expect(save.questLists.personal.map((quest: Quest) => [quest.title, quest.dueDate ?? null, quest.completed])).toEqual([
      ["Review biology notes", null, false],
      ["Tidy the desk", null, true],
      [QUICK_ERRAND, null, false],
      [DATED, "2026-10-22", false],
    ]);
    for (const quest of save.questLists.personal as Quest[]) {
      expect(quest).not.toHaveProperty("repeatSchedule");
      expect(quest).not.toHaveProperty("selectedDays");
    }

    for (const field of [
      "completionHistory",
      "personalXpByQuestId",
      "personalCompletedOnByQuestId",
      "legacyXpBonus",
      "discoveredPlantIds",
      "pendingPlantGiftIds",
      "starterPlantGiftPending",
      "categoryLists",
    ] as const) {
      expect(save[field], field).toEqual(fixture.save[field]);
    }
  });

  test("backs up the original once, and later loads change nothing", async ({ page }) => {
    await loadFixture(page);
    await expect.poll(async () => JSON.stringify(await saved(page))).not.toContain('"schedule"');
    expect(await readStorage(page, VALID_BACKUP_KEY)).toBe(ORIGINAL);
    expect(await readStorage(page, INVALID_BACKUP_KEY)).toBeNull();
    const afterFirstLoad = await readStorage(page, QUEST_SAVE_KEY);

    await reloadApp(page);
    await reloadApp(page);

    expect(await readStorage(page, QUEST_SAVE_KEY)).toBe(afterFirstLoad);
    expect(await readStorage(page, VALID_BACKUP_KEY)).toBe(ORIGINAL);
    expect((await page.evaluate(() => Object.keys(window.localStorage))).sort()).toEqual([VALID_BACKUP_KEY, QUEST_SAVE_KEY].sort());
  });

  test("rows show the real schedules and due dates, not the old text", async ({ page }) => {
    await loadFixture(page);

    await expect(questRow(dailyPanel(page), QUICK_HABIT)).toContainText("Wellness · Every day");
    await expect(questRow(dailyPanel(page), MON_WED)).toContainText("Wellness · Mon, Wed");
    await expect(questRow(personalPanel(page), DATED)).toContainText("Study · Due tomorrow");
    await expect(questRow(personalPanel(page), QUICK_ERRAND).getByText("Personal", { exact: true })).toBeVisible();
    await expect(questRow(personalPanel(page), "Review biology notes").getByText("Study", { exact: true })).toBeVisible();
    await expect(questRow(personalPanel(page), "Review biology notes")).not.toContainText("Due today");
  });

  test("completion history keeps every day, including a deleted quest's completion", async ({ page }) => {
    await loadFixture(page);
    await openApp(page, "/completion-history");

    const monday = historyDateSection(page, "Monday, October 19, 2026");
    await monday.locator("summary").click();
    await expect(monday).toContainText("8 completions");
    await expect(historyCard(page, "Finish portfolio moodboard")).toContainText("+20 XP");
    await expect(historyCard(page, "Tidy the desk")).toContainText("+5 XP");
    await expect(monday.getByRole("article").filter({ hasText: MON_WED })).toContainText("+20 XP");

    await expect(historyDateSection(page, "Tuesday, October 20, 2026")).toContainText("5 completions");
    await expect(historyDateSection(page, "Wednesday, October 21, 2026")).toContainText("2 completions");
  });

  test("gifts and plants carry over, and a waiting gift can still be unwrapped", async ({ page }) => {
    await loadFixture(page);
    await expect(page.getByRole("progressbar", { name: "XP progress toward Lavender" })).toBeVisible();

    await openApp(page, "/plant-journal");
    const summary = page.getByRole("region", { name: "Plant collection progress" });
    await expect(summary).toContainText("1 of 16 plants");
    await expect(summary).toContainText("130 XP in your ledger");
    await expect(summary).toContainText("Lavender");

    await page.getByRole("button", { name: "Unwrap gift" }).click();
    await expect(page.getByText("Daisy has joined your collection!")).toBeVisible();
    await expect(summary).toContainText("2 of 16 plants");

    await reloadApp(page);
    await expect(summary).toContainText("2 of 16 plants");
    expect((await saved(page)).discoveredPlantIds).toEqual(["fern", "daisy"]);
  });

  test("scheduling, streaks, and XP keep working on the following days", async ({ page }) => {
    await loadFixture(page);
    await expectStreak(page, 2);

    await completeQuest(page, QUICK_HABIT);
    await expect(progressText(page).getByText("35 / 150 XP", { exact: true })).toBeVisible();

    // Wednesday was left unfinished, so it ends the streak once it is over.
    await advanceToDay(page, 1, "Thursday, October 22");
    await expect(questRow(dailyPanel(page), MON_WED)).toHaveCount(0);
    await expect(questRow(personalPanel(page), DATED)).toContainText("Due today");
    await expectStreak(page, 0);
    for (const title of [...STARTER_DAILY, QUICK_HABIT]) await completeQuest(page, title);
    await expectStreak(page, 1);
    await expect(progressText(page).getByText("65 / 150 XP", { exact: true })).toBeVisible();

    await advanceToDay(page, 1, "Friday, October 23");
    await expect(questRow(personalPanel(page), DATED).getByText("Past Due", { exact: true })).toBeVisible();
    await expect(questRow(dailyPanel(page), MON_WED)).toHaveCount(0);

    await advanceToDay(page, 3, "Monday, October 26");
    await expect(questRow(dailyPanel(page), MON_WED)).toBeVisible();
    await expect(page.getByRole("button", { name: `Complete: ${MON_WED}`, exact: true })).toBeEnabled();
    await expect(progressText(page).getByText("65 / 150 XP", { exact: true })).toBeVisible();
  });

  test("a converted quest can be edited without losing its completion", async ({ page }) => {
    await loadFixture(page);

    await page.getByRole("button", { name: `Edit ${MON_WED}`, exact: true }).click();
    await expect(page.getByRole("combobox", { name: "Repeat", exact: true })).toContainText("Selected days");
    await expect(page.getByRole("button", { name: "Wed", exact: true })).toHaveAttribute("aria-pressed", "true");
    await chooseOption(page, "Difficulty", "Easy · 5 XP");
    await page.getByRole("button", { name: "Save changes" }).click();
    await expect(page).toHaveURL(/\/$/);

    await expect(page.getByRole("button", { name: `Mark incomplete: ${MON_WED}`, exact: true })).toBeVisible();
    await expect(progressText(page).getByText("30 / 150 XP", { exact: true })).toBeVisible();
    expect(JSON.stringify(await saved(page))).not.toContain('"schedule"');
  });

  // Normal play on main cannot produce these two fields, so this test adds them to the real save.
  test("a legacy XP bonus and a deleted-completion count are preserved", async ({ page }) => {
    await loadFixture(page, { ...fixture.save, legacyXpBonus: 40, deletedLegacyPersonalCompletionCount: 2 });

    // 130 earned plus the 40 bonus is 170 XP, which is 70 into level 2.
    await expect(progressText(page).getByText("70 / 150 XP", { exact: true })).toBeVisible();
    await expect(progressText(page).getByText("Level 2", { exact: true })).toBeVisible();
    await expect(progressText(page)).toContainText(/17\s*Quests completed/);
    await expect(progressText(page)).toContainText("13 daily · 4 personal");

    await reloadApp(page);
    await expect(progressText(page).getByText("70 / 150 XP", { exact: true })).toBeVisible();
    const save = await saved(page);
    expect(save.legacyXpBonus).toBe(40);
    expect(save.deletedLegacyPersonalCompletionCount).toBe(2);

    await openApp(page, "/completion-history");
    await expect(page.getByRole("heading", { name: "Earlier completions" })).toBeVisible();
    await expect(page.getByText("2 completions have no saved quest ID or individual details.")).toBeVisible();
  });
});

test.describe("Saves from before schema version 5", () => {
  const baseSave = {
    categoryLists: { daily: ["Wellness"], personal: ["Study"] },
  };
  const oldDaily = { id: "old-daily", title: "Old daily", category: "Wellness", schedule: "Every day", difficulty: "Easy", completed: false };
  const oldPersonal = { id: "old-personal", title: "Old personal", category: "Study", schedule: "Due today", difficulty: "Hard", completed: true };

  test("a version 4 save keeps its XP and level, and gets its plants through the migration", async ({ page }) => {
    const original = JSON.stringify({
      ...baseSave,
      schemaVersion: 4,
      questLists: { daily: [oldDaily], personal: [oldPersonal] },
      completionHistory: {
        "2026-10-18": {
          scheduledQuestIds: ["old-daily"],
          completedQuestIds: ["old-daily"],
          xpAwardedByQuestId: { "old-daily": 40 },
        },
      },
      personalXpByQuestId: { "old-personal": 20 },
      personalCompletedOnByQuestId: { "old-personal": "2026-10-18" },
      legacyXpBonus: 500,
    });
    await seedStorage(page, { [QUEST_SAVE_KEY]: original });
    await openApp(page);

    // 40 + 20 + 500 = 560 XP: levels take 100, 150, and 200, leaving 110 of 250 into level 4.
    await expect(progressText(page).getByText("110 / 250 XP", { exact: true })).toBeVisible();
    await expect(progressText(page).getByText("Level 4", { exact: true })).toBeVisible();
    await expect(progressText(page)).toContainText(/2\s*Quests completed/);
    await expectStreak(page, 1);
    await expect(questRow(dailyPanel(page), "Old daily")).toContainText("Wellness · Every day");
    await expect(page.getByRole("button", { name: "Mark incomplete: Old personal", exact: true })).toBeVisible();

    // Before gifts existed, plants up to 450 XP were collected on reaching them. Tulip (550) arrives as a gift.
    await expect(page.getByText("8 of 16 plants discovered")).toBeVisible();
    await expect(page.getByRole("link", { name: "Plant Journal, 1 gift waiting" })).toBeVisible();

    await expect.poll(async () => (await saved(page)).schemaVersion).toBe(5);
    const save = await saved(page);
    expect(save.discoveredPlantIds).toEqual(["fern", "daisy", "cactus", "sunflower", "lavender", "monstera", "moonflower", "golden-bonsai"]);
    expect(save.pendingPlantGiftIds).toEqual(["tulip"]);
    expect(save.legacyXpBonus).toBe(500);
    expect(save.questLists.daily[0].repeatSchedule).toBe("Every day");
    expect(JSON.stringify(save.questLists)).not.toContain('"schedule"');
    expect(await readStorage(page, VALID_BACKUP_KEY)).toBe(original);

    await reloadApp(page);
    await expect(progressText(page).getByText("110 / 250 XP", { exact: true })).toBeVisible();
    await expect(page.getByText("8 of 16 plants discovered")).toBeVisible();
    expect(await readStorage(page, VALID_BACKUP_KEY)).toBe(original);
  });

  test("a version 4 save still waiting on its starter gift keeps it wrapped", async ({ page }) => {
    await seedStorage(page, {
      [QUEST_SAVE_KEY]: JSON.stringify({
        ...baseSave,
        schemaVersion: 4,
        questLists: { daily: [oldDaily], personal: [] },
        legacyXpBonus: 30,
        starterPlantGiftPending: true,
      }),
    });
    await openApp(page);

    await expect(page.getByText("1 of 16 plants discovered")).toBeVisible();
    await expect(page.getByRole("link", { name: "Plant Journal, 1 gift waiting" })).toBeVisible();
    await expect.poll(async () => (await saved(page)).pendingPlantGiftIds).toEqual(["fern"]);
    expect((await saved(page)).discoveredPlantIds).toEqual(["daisy"]);
  });

  test("a save with no version keeps XP from completed quests that have no recorded awards", async ({ page }) => {
    const original = JSON.stringify({
      ...baseSave,
      questLists: {
        daily: [{ ...oldDaily, id: "flagged-daily", title: "Flagged daily", difficulty: "Hard", completed: true }],
        personal: [{ ...oldPersonal, difficulty: "Medium" }],
      },
      deletedLegacyPersonalCompletionCount: 2,
    });
    await seedStorage(page, { [QUEST_SAVE_KEY]: original });
    await openApp(page);

    // 10 for the Personal Quest as an award, and 20 for the daily flag as a one-time bonus.
    await expect(progressText(page).getByText("30 / 100 XP", { exact: true })).toBeVisible();
    await expect(page.getByText("2 of 16 plants discovered")).toBeVisible();
    await expect(progressText(page)).toContainText(/3\s*Quests completed/);

    await expect.poll(async () => (await saved(page)).schemaVersion).toBe(5);
    const save = await saved(page);
    expect(save.personalXpByQuestId).toEqual({ "old-personal": 10 });
    expect(save.legacyXpBonus).toBe(20);
    expect(save.deletedLegacyPersonalCompletionCount).toBe(2);
    expect(save.discoveredPlantIds).toEqual(["fern", "daisy"]);
    expect(await readStorage(page, VALID_BACKUP_KEY)).toBe(original);

    await reloadApp(page);
    await expect(progressText(page).getByText("30 / 100 XP", { exact: true })).toBeVisible();
    expect((await saved(page)).legacyXpBonus).toBe(20);

    await openApp(page, "/completion-history");
    await expect(page.getByRole("heading", { name: "Earlier completions" })).toBeVisible();
    await expect(page.getByText("3 completions", { exact: true })).toBeVisible();
  });
});

test.describe("When a backup cannot be written", () => {
  // A switch in session storage lets a test turn the failure off again, like space being freed up.
  async function failBackupWrites(page: Page) {
    await page.addInitScript(() => {
      if (window.sessionStorage.getItem("e2e-allow-backup")) return;
      const originalSetItem = Storage.prototype.setItem;
      Storage.prototype.setItem = function (key: string, value: string) {
        if (this === window.localStorage && key.includes("backup")) throw new Error("Storage is full");
        return originalSetItem.call(this, key, value);
      };
    });
  }

  test("a save needing conversion is left exactly as it was, and the app stays usable", async ({ page }) => {
    await failBackupWrites(page);
    await page.clock.setSystemTime(WEDNESDAY);
    await seedStorage(page, { [QUEST_SAVE_KEY]: ORIGINAL });
    await openApp(page);

    // Quests are converted in memory, so this session behaves normally.
    await expect(questRow(dailyPanel(page), MON_WED)).toContainText("Wellness · Mon, Wed");
    await expect(progressText(page).getByText("30 / 150 XP", { exact: true })).toBeVisible();
    await completeQuest(page, QUICK_HABIT);
    await expect(progressText(page).getByText("35 / 150 XP", { exact: true })).toBeVisible();

    // Nothing partial is written: not the conversion, not the completion, not a backup.
    expect(await readStorage(page, QUEST_SAVE_KEY)).toBe(ORIGINAL);
    expect(await readStorage(page, VALID_BACKUP_KEY)).toBeNull();

    await reloadApp(page);
    expect(await readStorage(page, QUEST_SAVE_KEY)).toBe(ORIGINAL);
    await expect(progressText(page).getByText("30 / 150 XP", { exact: true })).toBeVisible();
  });

  test("the conversion completes normally once a backup can be written", async ({ page }) => {
    await failBackupWrites(page);
    await page.clock.setSystemTime(WEDNESDAY);
    await seedStorage(page, { [QUEST_SAVE_KEY]: ORIGINAL });
    await openApp(page);
    expect(await readStorage(page, QUEST_SAVE_KEY)).toBe(ORIGINAL);

    await page.evaluate(() => window.sessionStorage.setItem("e2e-allow-backup", "true"));
    await reloadApp(page);

    await expect.poll(async () => JSON.stringify(await saved(page))).not.toContain('"schedule"');
    expect(await readStorage(page, VALID_BACKUP_KEY)).toBe(ORIGINAL);
    await expect(progressText(page).getByText("30 / 150 XP", { exact: true })).toBeVisible();
  });

  test("an unreadable save is not overwritten with starter quests", async ({ page }) => {
    await failBackupWrites(page);
    await seedStorage(page, { [QUEST_SAVE_KEY]: "{not valid json" });
    await openApp(page);

    await expect(dailyPanel(page).getByText("0 / 4 done")).toBeVisible();
    await completeQuest(page, STARTER_DAILY[0]);

    expect(await readStorage(page, QUEST_SAVE_KEY)).toBe("{not valid json");
    expect(await readStorage(page, INVALID_BACKUP_KEY)).toBeNull();
  });

  test("a clean save has nothing to back up, so it keeps saving normally", async ({ page }) => {
    await failBackupWrites(page);
    await openApp(page);
    await completeQuest(page, STARTER_DAILY[0]);

    await reloadApp(page);
    await expect(page.getByRole("button", { name: `Mark incomplete: ${STARTER_DAILY[0]}`, exact: true })).toBeVisible();
  });
});

test.describe("Exporting data", () => {
  async function exportBackup(page: Page) {
    await openApp(page, "/settings");
    await expect(page.getByLabel("Display name")).toBeEnabled();
    const downloadPromise = page.waitForEvent("download");
    await page.getByRole("button", { name: "Export data as JSON" }).click();
    return JSON.parse(await readFile(await (await downloadPromise).path(), "utf8"));
  }

  test("a converted save exports structured recurrence, no schedule text, and all its progress", async ({ page }) => {
    await loadFixture(page);

    const backup = await exportBackup(page);

    expect(JSON.stringify(backup)).not.toContain('"schedule"');
    expect(backup.totalXp).toBe(130);
    const { questData } = backup;
    expect(questData.questLists.daily.map((quest: Quest) => [quest.repeatSchedule, quest.selectedDays])).toEqual([
      ...Array.from({ length: 5 }, () => ["Every day", ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]]),
      ["Selected days", ["Mon", "Wed"]],
    ]);
    expect(questData.questLists.personal[3].dueDate).toBe("2026-10-22");
    expect(questData.completionHistory).toEqual(fixture.save.completionHistory);
    expect(questData.personalXpByQuestId).toEqual(fixture.save.personalXpByQuestId);
    expect(questData.personalCompletedOnByQuestId).toEqual(fixture.save.personalCompletedOnByQuestId);
    expect(questData.discoveredPlantIds).toEqual(fixture.save.discoveredPlantIds);
    expect(questData.pendingPlantGiftIds).toEqual(fixture.save.pendingPlantGiftIds);
    expect(questData.legacyXpBonus).toBe(fixture.save.legacyXpBonus);
  });

  test("a new install exports structured recurrence and no schedule text", async ({ page }) => {
    await openApp(page);
    await completeQuest(page, STARTER_DAILY[0]);
    await completeQuest(page, "Tidy the desk");

    const backup = await exportBackup(page);

    expect(JSON.stringify(backup)).not.toContain('"schedule"');
    expect(backup.totalXp).toBe(10);
    expect(backup.questData.questLists.daily[0].repeatSchedule).toBe("Every day");
    expect(backup.questData.questLists.personal[0]).not.toHaveProperty("repeatSchedule");
    expect(backup.questData.completionHistory["2026-10-19"].completedQuestIds).toEqual(["water"]);
    expect(backup.questData.personalCompletedOnByQuestId).toEqual({ desk: "2026-10-19" });
  });
});
